import React from 'react';
import './ExtractedDetails.css';

/**
 * Component for showing parsed resume information such as skills, experience, and contact details.
 */
const ExtractedDetails = () => {
  return (
    <div className="extracted-details">
      <h2>Extracted Details</h2>
      <p>Parsed information from the AI service will be displayed here after analysis completes.</p>
    </div>
  );
};

export default ExtractedDetails;
